<?php $caOnly=$r['kind']==='assessment'&&acPendingESE($r); ?>
<section class="card"><h2><?=$caOnly?'Continuous assessment marks':'Weighted marks preview'?></h2>
<p>Each contribution = raw mark ÷ maximum mark × weight. <?=$caOnly?'CA is shown separately while ESE is pending. CA total is the weighted contribution, not a final mark out of 100.':'Pass requires CA ≥ 40% of its weight, ESE ≥ 40% of its weight where applicable, and total ≥ 50. Successful re-assessment is capped at 50.'?></p>
<div class="table-wrap"><table class="ac-bordered"><thead><tr><th>Sl. No.</th><th>Student</th><th>ID</th><?php foreach($r['metadata']['components']as $c):if($caOnly&&$c['type']==='ESE')continue;?><th><?=e($c['name'])?> / <?=e($c['max'])?> (<?=e($c['weight'])?>%)</th><?php endforeach;?><th>CA total / <?=e(array_sum(array_map(fn($c)=>$c['type']==='CA'?$c['weight']:0,$r['metadata']['components'])))?></th><?php if(!$caOnly):?><th>ESE</th><th>Total / 100</th><th>Result</th><?php endif;?></tr></thead><tbody>
<?php foreach($r['entries']as $i=>$v):$m=acMarks($r,$v);?><tr><td><?=$i+1?></td><td><?=e($v['student_name'])?></td><td><?=e($v['student_id'])?></td><?php foreach($v['marks']as $j=>$mark):if($caOnly&&$r['metadata']['components'][$j]['type']==='ESE')continue;?><td><?=e($mark??'Pending')?></td><?php endforeach;?><td><b><?=e($m['ca'])?></b></td><?php if(!$caOnly):?><td><?=e($m['ese']??'N/A')?></td><td><?=e($m['total']??'Pending')?></td><td><?=e($m['result'])?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></section>
